object Evolve1 {
    const val BOOK_ID = "evolve_1"

    fun getContent(chapterNumber: Int): LessonContent = when (chapterNumber) {
        1 -> unit1(); 2 -> unit2(); 3 -> unit3(); 4 -> unit4()
        5 -> unit5(); 6 -> unit6(); 7 -> unit7(); 8 -> unit8()
        9 -> unit9(); 10 -> unit10(); 11 -> unit11(); 12 -> unit12()
        else -> LessonContent(BOOK_ID, chapterNumber, "Coming Soon", "به‌زودی...",
            vocabulary = emptyList(), grammar = emptyList(), conversation = emptyList(), quiz = emptyList())
    }

    private fun base(n: Int, title: String, fa: String, objectives: List<String>,
        vocab: List<VocabWord>, grammar: List<GrammarSection>, dialogue: List<DialogueLine>,
        quiz: List<QuizQuestion>, idioms: List<IdiomExpression> = emptyList(),
        phrasal: List<PhrasalVerb> = emptyList(), pronunciation: List<PronunciationTip> = emptyList(),
        culture: List<CulturalNote> = emptyList(), mistakes: List<CommonMistake> = emptyList(),
        comprehension: List<ComprehensionQuestion> = emptyList(), speaking: List<SpeakingTask> = emptyList(),
        writing: List<WritingTask> = emptyList()
    ) = LessonContent(BOOK_ID, n, title, fa, objectives, vocab, idioms, phrasal, pronunciation,
        culture, grammar, mistakes, dialogue, comprehension, speaking, writing, quiz)

    private fun v(e: String, p: String, ex: String, ep: String, pos: String = "noun") =
        VocabWord(e, p, partOfSpeech = pos, example = ex, examplePersian = ep)
    private fun d(s: String, e: String, p: String) = DialogueLine(s, e, p)
    private fun q(question: String, options: List<String>, correct: Int) =
        QuizQuestion(question, options, correct)

